/* Generated from modern-minimal.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='modern-minimal'],
[data-ui-theme='modern-minimal'] {
  color-scheme: light;
  --ui-background: oklch(1.00 0 0);
  --ui-foreground: oklch(0.32 0 0);
  --ui-card: oklch(1.00 0 0);
  --ui-card-foreground: oklch(0.32 0 0);
  --ui-popover: oklch(1.00 0 0);
  --ui-popover-foreground: oklch(0.32 0 0);
  --ui-primary: oklch(0.62 0.19 259.76);
  --ui-primary-foreground: oklch(1.00 0 0);
  --ui-secondary: oklch(0.97 0 0);
  --ui-secondary-foreground: oklch(0.45 0.03 257.68);
  --ui-muted: oklch(0.98 0 0);
  --ui-muted-foreground: oklch(0.55 0.02 264.41);
  --ui-accent: oklch(0.95 0.03 233.56);
  --ui-accent-foreground: oklch(0.38 0.14 265.59);
  --ui-destructive: oklch(0.64 0.21 25.39);
  --ui-destructive-foreground: oklch(1.00 0 0);
  --ui-border: oklch(0.93 0.01 261.82);
  --ui-input: oklch(0.93 0.01 261.82);
  --ui-ring: oklch(0.62 0.19 259.76);
  --ui-chart-1: oklch(0.62 0.19 259.76);
  --ui-chart-2: oklch(0.55 0.22 262.96);
  --ui-chart-3: oklch(0.49 0.22 264.43);
  --ui-chart-4: oklch(0.42 0.18 265.55);
  --ui-chart-5: oklch(0.38 0.14 265.59);
  --ui-sidebar: oklch(0.98 0 0);
  --ui-sidebar-foreground: oklch(0.14 0 0);
  --ui-sidebar-primary: oklch(0.20 0 0);
  --ui-sidebar-primary-foreground: oklch(0.98 0 0);
  --ui-sidebar-accent: oklch(0.97 0 0);
  --ui-sidebar-accent-foreground: oklch(0.20 0 0);
  --ui-sidebar-border: oklch(0.92 0 0);
  --ui-sidebar-ring: oklch(0.71 0 0);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Source Serif 4', ui-serif, serif;
  --ui-font-heading: 'Inter', ui-sans-serif, sans-serif;
  --ui-font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 3px 0px oklch(0.00 0 0 / 0.05);
  --ui-shadow-panel:
    0 1px 3px 0px oklch(0.00 0 0 / 0.10), 0 4px 6px -1px oklch(0.00 0 0 / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='modern-minimal'].dark,
[data-ui-theme='modern-minimal'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.20 0 0);
  --ui-foreground: oklch(0.92 0 0);
  --ui-card: oklch(0.27 0 0);
  --ui-card-foreground: oklch(0.92 0 0);
  --ui-popover: oklch(0.27 0 0);
  --ui-popover-foreground: oklch(0.92 0 0);
  --ui-primary: oklch(0.62 0.19 259.76);
  --ui-primary-foreground: oklch(1.00 0 0);
  --ui-secondary: oklch(0.27 0 0);
  --ui-secondary-foreground: oklch(0.92 0 0);
  --ui-muted: oklch(0.27 0 0);
  --ui-muted-foreground: oklch(0.72 0 0);
  --ui-accent: oklch(0.38 0.14 265.59);
  --ui-accent-foreground: oklch(0.88 0.06 254.63);
  --ui-destructive: oklch(0.64 0.21 25.39);
  --ui-destructive-foreground: oklch(1.00 0 0);
  --ui-border: oklch(0.37 0 0);
  --ui-input: oklch(0.37 0 0);
  --ui-ring: oklch(0.62 0.19 259.76);
  --ui-chart-1: oklch(0.71 0.14 254.69);
  --ui-chart-2: oklch(0.62 0.19 259.76);
  --ui-chart-3: oklch(0.55 0.22 262.96);
  --ui-chart-4: oklch(0.49 0.22 264.43);
  --ui-chart-5: oklch(0.42 0.18 265.55);
  --ui-sidebar: oklch(0.21 0.01 285.93);
  --ui-sidebar-foreground: oklch(0.99 0 0);
  --ui-sidebar-primary: oklch(0.49 0.24 264.40);
  --ui-sidebar-primary-foreground: oklch(0.99 0 0);
  --ui-sidebar-accent: oklch(0.27 0.01 286.10);
  --ui-sidebar-accent-foreground: oklch(0.99 0 0);
  --ui-sidebar-border: oklch(1.00 0 0 / 10%);
  --ui-sidebar-ring: oklch(0.55 0.02 285.93);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Source Serif 4', ui-serif, serif;
  --ui-font-heading: 'Inter', ui-sans-serif, sans-serif;
  --ui-font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 3px 0px oklch(0.00 0 0 / 0.05);
  --ui-shadow-panel:
    0 1px 3px 0px oklch(0.00 0 0 / 0.10), 0 4px 6px -1px oklch(0.00 0 0 / 0.10);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
